import json
import os
import requests
from contextlib import asynccontextmanager

import anthropic
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

from dal import ItemCreate, ItemDAL, ItemRead, get_client, get_collection

# This section of code was generated by Claude Sonnet 4.6
# -------------------------------------------------------
MODEL_SERVICE_URL = os.environ.get("MODEL_SERVICE_URL", "http://localhost:8001")


@asynccontextmanager
async def lifespan(app: FastAPI):
    mongo_url = os.environ.get("MONGO_URL", "mongodb://localhost:27017")
    client = get_client(mongo_url)
    app.state.dal = ItemDAL(get_collection(client))
    yield
    client.close()


app = FastAPI(lifespan=lifespan)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)
# -------------------------------------------------------

@app.get("/items", response_model=list[ItemRead], status_code=200)
async def get_all_items():
    return await app.state.dal.get_all()


@app.get("/items/{item_id}", response_model=ItemRead, status_code=200)
async def get_item(item_id: str):
    item = await app.state.dal.get_one(item_id)
    if item is None:
        raise HTTPException(status_code=404, detail="Item Not Found")
    return item


@app.post("/items", response_model=ItemRead, status_code=201)
async def create_item(item: ItemCreate):
    return await app.state.dal.create(item)


@app.put("/items/{item_id}", response_model=ItemRead, status_code=200)
async def update_item(item_id: str, item: ItemCreate):
    updated = await app.state.dal.update(item_id, item)
    if updated is None:
        raise HTTPException(status_code=404, detail="Item not found")
    return updated


@app.delete("/items/{item_id}", status_code=200)
async def delete_item(item_id: str):
    deleted = await app.state.dal.delete(item_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Item not found")
    return {"message": "Item deleted", "id": item_id}


class PredictionRequest(BaseModel):
    features: list[float]

@app.post("/predict")
def predict(req: PredictionRequest):
    try:
        response = requests.post(
            f"{MODEL_SERVICE_URL}/predict",
            json={"features": req.features},
            timeout=10,
        )
        response.raise_for_status()
        return response.json()
    except requests.exceptions.ConnectionError:
        raise HTTPException(status_code=503, detail="Model service unavailable")
    except requests.exceptions.HTTPError as e:
        raise HTTPException(status_code=e.response.status_code, detail=e.response.text)

# This section of code was generated by Claude Sonnet 4.6
_llm = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY from environment

_CHAT_SYSTEM = (
    "You are a helpful assistant for the Item Manager app. "
    "Help users organize, name, and describe their inventory items. "
    "Suggest clear item names, concise descriptions, and practical categorization tips. "
    "Be brief and actionable."
)

_ANALYZE_SYSTEM = (
    "You are an item classification assistant. Analyze the provided item name and description, "
    "then respond with ONLY valid JSON in this exact format:\n"
    '{\n'
    '  "categories": ["category1", "category2"],\n'
    '  "tags": ["tag1", "tag2", "tag3"],\n'
    '  "sentiment": "positive" | "negative" | "neutral",\n'
    '  "summary": "one sentence summary of the item"\n'
    '}\n'
    "Do not include any text outside the JSON object."
)

_ANALYZE_FEW_SHOT = (
    'Example:\n'
    'Input: "Blue Mechanical Keyboard - Compact TKL with Cherry MX Blue switches, RGB backlight, USB-C. Great for gaming."\n'
    'Output: {"categories": ["electronics", "peripherals"], "tags": ["keyboard", "mechanical", "RGB", "gaming", "USB-C"], '
    '"sentiment": "positive", "summary": "Compact RGB mechanical gaming keyboard with Cherry MX Blue switches."}'
)


class ChatRequest(BaseModel):
    message: str
    conversation_history: list = []


class ChatResponse(BaseModel):
    reply: str
    conversation_history: list


@app.post("/chat", response_model=ChatResponse)
def chat(request: ChatRequest):
    messages = request.conversation_history + [{"role": "user", "content": request.message}]
    try:
        response = _llm.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=512,
            system=_CHAT_SYSTEM,
            messages=messages,
        )
        reply = response.content[0].text
        updated_history = messages + [{"role": "assistant", "content": reply}]
        return ChatResponse(reply=reply, conversation_history=updated_history)
    except anthropic.APIStatusError as e:
        raise HTTPException(status_code=e.status_code, detail=e.message)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


class AnalyzeRequest(BaseModel):
    content: str


@app.post("/analyze")
def analyze(request: AnalyzeRequest):
    prompt = _ANALYZE_FEW_SHOT + "\n\nNow analyze this:\n" + request.content
    try:
        response = _llm.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=512,
            system=_ANALYZE_SYSTEM,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
        )
        raw = response.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("```", 2)[1]
            if raw.startswith("json"):
                raw = raw[4:]
            raw = raw.strip()
        result = json.loads(raw)
        for field in ("categories", "tags", "sentiment", "summary"):
            if field not in result:
                raise ValueError(f"Missing field: {field}")
        return result
    except json.JSONDecodeError:
        raise HTTPException(status_code=422, detail="LLM returned invalid JSON. Try again.")
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))
    except anthropic.APIStatusError as e:
        raise HTTPException(status_code=e.status_code, detail=e.message)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
# --------------------------------------------------------------

app.mount("/", StaticFiles(directory="static", html=True), name="static")
